describe('Email Field Inline Validation', () => {
    beforeEach(() => {
        cy.visit('/your-form-page-url'); // Replace with the actual URL of the form page
    });

    it('should show valid message for a correctly formatted email', () => {
        cy.get('input[name="email"]') // Replace with the actual selector for the email input
            .type('test@example.com')
            .should('have.class', 'valid'); // Assuming 'valid' class is added for valid email
        cy.get('.validation-message') // Replace with the actual selector for the validation message
            .should('contain', 'Email is valid'); // Assuming this is the message displayed for valid email
    });

    it('should show error message for an incorrectly formatted email', () => {
        cy.get('input[name="email"]') // Replace with the actual selector for the email input
            .type('invalid-email')
            .should('have.class', 'invalid'); // Assuming 'invalid' class is added for invalid email
        cy.get('.validation-message') // Replace with the actual selector for the validation message
            .should('contain', 'Please enter a valid email address'); // Assuming this is the message displayed for invalid email
    });
});
